Subroutine VerTotal()
  Write total;
EndSubroutine

Algorithm Principal
  Define total As Integer <- 10;
  VerTotal();
EndAlgorithm

Algorithm FueraAmbito
  Define n As Integer <- 3;
  If n > 0 Then
    Define doble As Integer <- n * 2;
    Write doble;
  EndIf
  Write doble;
EndAlgorithm

Algorithm Ambitos
  Define x As Integer <- 1;
  If x > 0 Then
    Define x As Integer <- 2;
    Write "dentro: ", x;
  EndIf
  Write "fuera: ", x;
EndAlgorithm
